// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(address actor, uint96 amount, uint32 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 amt = bound(uint256(amount), 0, 1 ether);
        // configure a WORKING log file before initialization
        LogAccept workingLog = new LogAccept();
        c.SetLogFile(address(workingLog));
        // the configured C accepts deposits through Put for every actor/amount/lockTime
        vm.deal(actor, amt);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amt}(lockTime) { ok = true; } catch { ok = false; }
        // For EVERY admissible input, a deposit succeeds when the log is set and functional;
        // the mutant never stored the log (Log == address(0)), so Put reverts for all these inputs.
        assertTrue(ok, "Put must succeed when a working log file is configured");
    }
}

contract LogAccept {
    function AddMessage(address, uint, string calldata) external pure {}
}
